  1	// Point-in-time view of the resources a model competes for: GPU memory (and
  2	// the other processes holding it), system RAM and free disk under /data.
  3	// Re-read immediately before every launch, because the host Ollama service
  4	// and other granted workspaces share the same GPU.
  5	
  6	import { execFile } from 'node:child_process';
  7	import fs from 'node:fs';
  8	import os from 'node:os';
  9	
 10	// The Box GPU wiring binds the host nvidia-smi here (the override is a test seam).
 11	export const NVIDIA_SMI = process.env.LOCAL_LLM_NVIDIA_SMI || '/usr/local/nvidia/bin/nvidia-smi';
 12	const MIB = 1024 * 1024;
 13	
 14	function run(execFileImpl, command, args, timeoutMs = 10_000) {
 15	    return new Promise((resolve) => {
 16	        execFileImpl(command, args, { timeout: timeoutMs, encoding: 'utf8' }, (error, stdout, stderr) => {
 17	            resolve({ ok: !error, stdout: String(stdout || ''), stderr: String(stderr || ''), error });
 18	        });
 19	    });
 20	}
 21	
 22	function csvRows(text) {
 23	    return text.split('\n').map((line) => line.trim()).filter(Boolean)
 24	        .map((line) => line.split(',').map((cell) => cell.trim()));
 25	}
 26	
 27	export async function readGpu({ execFileImpl = execFile, nvidiaSmi = NVIDIA_SMI, env = process.env } = {}) {
 28	    const query = await run(execFileImpl, nvidiaSmi, [
 29	        '--query-gpu=name,memory.total,memory.used,memory.free,driver_version',
 30	        '--format=csv,noheader,nounits',
 31	    ]);
 32	    if (!query.ok) {
 33	        // Ploinky starts this agent without the GPU device when the Box has no
 34	        // GPU for it, and says why (containerSecurity.gpu, Ploinky D14).
 35	        const attachReason = env.PLOINKY_GPU_STATUS === 'unavailable' && env.PLOINKY_GPU_REASON
 36	            ? String(env.PLOINKY_GPU_REASON).slice(0, 500)
 37	            : null;
 38	        const reason = query.error?.code === 'ENOENT'
 39	            ? (attachReason
 40	                ? `No GPU is attached to this agent: ${attachReason}`
 41	                : 'No GPU is available to this agent. On the host, `ploinky gpu status` shows why: '
 42	                    + 'revoked: run `ploinky gpu grant --agent local-llms/local-llm`; '
 43	                    + 'not applied yet: run `ploinky start`; or the host has no usable GPU.')
 44	            : `nvidia-smi failed: ${(query.stderr || query.error?.message || '').trim().slice(0, 300)}`;
 45	        return { available: false, reason };
 46	    }
 47	    const [first] = csvRows(query.stdout);
 48	    if (!first || first.length < 5) return { available: false, reason: 'nvidia-smi reported no GPU' };
 49	    const [name, total, used, free, driver] = first;
 50	    const apps = await run(execFileImpl, nvidiaSmi, [
 51	        '--query-compute-apps=pid,process_name,used_memory',
 52	        '--format=csv,noheader,nounits',
 53	    ]);
 54	    const processes = apps.ok
 55	        ? csvRows(apps.stdout).map(([pid, processName, usedMemory]) => ({
 56	            pid: Number(pid), name: processName, usedBytes: Number(usedMemory) * MIB,
 57	        }))
 58	        : [];
 59	    return {
 60	        available: true,
 61	        name,
 62	        driverVersion: driver,
 63	        totalBytes: Number(total) * MIB,
 64	        usedBytes: Number(used) * MIB,
 65	        freeBytes: Number(free) * MIB,
 66	        processes,
 67	    };
 68	}
 69	
 70	export function readMemory({ fsApi = fs } = {}) {
 71	    const text = fsApi.readFileSync('/proc/meminfo', 'utf8');
 72	    const value = (key) => {
 73	        const match = new RegExp(`^${key}:\\s+(\\d+) kB$`, 'm').exec(text);
 74	        return match ? Number(match[1]) * 1024 : null;
 75	    };
 76	    return { totalBytes: value('MemTotal'), availableBytes: value('MemAvailable'), swapFreeBytes: value('SwapFree') };
 77	}
 78	
 79	function readText(fsApi, file) {
 80	    try {
 81	        return fsApi.readFileSync(file, 'utf8');
 82	    } catch {
 83	        return null;
 84	    }
 85	}
 86	
 87	// "0-3,8,10-11" -> [0, 1, 2, 3, 8, 10, 11]
 88	function parseCpuList(text) {
 89	    const cpus = [];
 90	    for (const part of String(text).trim().split(',')) {
 91	        const match = /^(\d+)(?:-(\d+))?$/.exec(part.trim());
 92	        if (!match) return null;
 93	        const first = Number(match[1]);
 94	        const last = match[2] === undefined ? first : Number(match[2]);
 95	        if (last < first || last - first > 4096) return null;
 96	        for (let cpu = first; cpu <= last; cpu += 1) cpus.push(cpu);
 97	    }
 98	    return cpus.length ? cpus : null;
 99	}
