101	/**
102	 * Physical CPU cores this process may run on: the CPUs its affinity or
103	 * cpuset allows, counted once per (package, core) so SMT siblings share one
104	 * core, and capped by a cgroup v2 CPU quota. Falls back to /proc/cpuinfo when
105	 * sysfs has no topology, then to the logical CPU count.
106	 */
107	export function physicalCoreCount({ fsApi = fs, availableParallelism = () => os.availableParallelism?.() ?? os.cpus().length } = {}) {
108	    const logical = Math.max(1, availableParallelism());
109	    const status = readText(fsApi, '/proc/self/status');
110	    const allowedMatch = status && /^Cpus_allowed_list:\s*(\S+)\s*$/m.exec(status);
111	    const allowed = allowedMatch ? parseCpuList(allowedMatch[1]) : null;
112	    const allowedSet = allowed ? new Set(allowed) : null;
113	
114	    let cores = null;
115	    if (allowed) {
116	        const seen = new Set();
117	        for (const cpu of allowed) {
118	            const base = `/sys/devices/system/cpu/cpu${cpu}/topology`;
119	            const pkg = readText(fsApi, `${base}/physical_package_id`);
120	            const core = readText(fsApi, `${base}/core_id`);
121	            if (pkg === null || core === null) {
122	                seen.clear();
123	                break;
124	            }
125	            seen.add(`${pkg.trim()}:${core.trim()}`);
126	        }
127	        if (seen.size) cores = seen.size;
128	    }
129	    if (cores === null) {
130	        const cpuinfo = readText(fsApi, '/proc/cpuinfo');
131	        const seen = new Set();
132	        for (const block of (cpuinfo || '').split(/\n\s*\n/)) {
133	            const field = (name) => new RegExp(`^${name}\\s*:\\s*(\\S+)`, 'm').exec(block)?.[1];
134	            const processor = field('processor');
135	            const core = field('core id');
136	            if (processor === undefined || core === undefined) continue;
137	            if (allowedSet && !allowedSet.has(Number(processor))) continue;
138	            seen.add(`${field('physical id') ?? 0}:${core}`);
139	        }
140	        cores = seen.size || logical;
141	    }
142	    const quota = readText(fsApi, '/sys/fs/cgroup/cpu.max');
143	    const quotaMatch = quota && /^(\d+)\s+(\d+)\s*$/.exec(quota.trim());
144	    if (quotaMatch && Number(quotaMatch[2]) > 0) {
145	        cores = Math.min(cores, Math.max(1, Math.ceil(Number(quotaMatch[1]) / Number(quotaMatch[2]))));
146	    }
147	    return cores;
148	}
