155	export async function readDisk(dataDir, { statfs = (target) => fs.promises.statfs(target) } = {}) {
156	    const stats = await statfs(dataDir);
157	    return { freeBytes: Number(stats.bavail) * Number(stats.bsize), totalBytes: Number(stats.blocks) * Number(stats.bsize) };
158	}
159	
160	export async function readSnapshot({ dataDir, execFileImpl, fsApi, statfs } = {}) {
161	    const [gpu, disk] = await Promise.all([
162	        readGpu({ execFileImpl }),
163	        readDisk(dataDir, { statfs }).catch((error) => ({ freeBytes: null, totalBytes: null, error: error.message })),
164	    ]);
165	    return {
166	        at: new Date().toISOString(),
167	        gpu,
168	        memory: readMemory({ fsApi }),
169	        disk,
170	        cpus: os.availableParallelism?.() ?? os.cpus().length,
171	    };
172	}
173	import { codedError } from './params.mjs';
174	import { ikLlamaCppRunner } from './ikLlamaCpp.mjs';
175	import { llamaCppRunner } from './llamaCpp.mjs';
176	import { lmStudioRunner } from './lmStudio.mjs';
177	import { ollamaRunner } from './ollama.mjs';
178	import { tabbyApiRunner } from './tabbyApi.mjs';
179	import { vllmRunner } from './vllm.mjs';
