181	// Every runner is an adapter (llamaServer.mjs shows the full shape): identity,
182	// the weight format it reads, its loopback port and per-start key, its
183	// parameter schema and form metadata, detection, the start-up pipeline, the
184	// chat model name, its admission policy and its log-report parser. The
185	// controller has no per-runner branches; adding a runner adds an adapter here.
186	// LM Studio is for internal use only, behind an operator switch (runners plan
187	// I9, Phase R7; DS000).
188	export const RUNNERS = Object.freeze({
189	    'llama.cpp': llamaCppRunner,
190	    'ik_llama.cpp': ikLlamaCppRunner,
191	    ollama: ollamaRunner,
192	    vllm: vllmRunner,
193	    tabbyapi: tabbyApiRunner,
194	    lmstudio: lmStudioRunner
195	});
