197	export function getRunner(id) {
198	    if (typeof id !== 'string' || !Object.hasOwn(RUNNERS, id)) {
199	        throw codedError('unknown_runner', `Unknown runner: ${String(id)}`, { runner: id });
200	    }
201	    return RUNNERS[id];
202	}
203	
204	/** The loopback port of every supported runner; two runners never share one. */
205	export function defaultPorts(runners = RUNNERS) {
206	    const ports = {};
207	    const owners = new Map();
208	    for (const runner of Object.values(runners)) {
209	        if (!runner.supported) continue;
210	        if (!Number.isInteger(runner.port)) throw new Error(`Runner ${runner.id} has no port`);
211	        if (owners.has(runner.port)) {
212	            throw new Error(`Runners ${owners.get(runner.port)} and ${runner.id} both use port ${runner.port}`);
213	        }
214	        owners.set(runner.port, runner.id);
215	        ports[runner.id] = runner.port;
216	    }
217	    return Object.freeze(ports);
218	}
219	
220	/** What the overview and the dashboard learn about each runner. */
221	export function runnerSummary(runner) {
222	    const { id, displayName, weightFormat, pinnedVersion, supported, paramSchema } = runner;
223	    return {
224	        id, displayName, weightFormat, pinnedVersion, supported, paramSchema,
225	        basicParams: runner.basicParams || [],
226	        moeParams: runner.moeParams || [],
227	    };
228	}
229	
230	export function runnerSummaries(runners = RUNNERS) {
231	    return Object.values(runners).map(runnerSummary);
232	}

  1	import { isAbsolute } from 'node:path';
  2	
  3	const API_KEY_PATTERN = /^[A-Za-z0-9_-]{32,128}$/;
  4	const PROBE_TIMEOUT_MS = 10000;
  5	const SNIPPET_LENGTH = 200;
  6	
  7	export class ParamError extends Error {
  8	    constructor(field, reason) {
  9	        super(`Invalid parameter ${field}: ${reason}`);
 10	        this.name = 'ParamError';
 11	        this.code = 'invalid_params';
 12	        this.details = { field, reason };
 13	    }
 14	}
 15	
 16	export function codedError(code, message, details) {
 17	    const error = new Error(message);
 18	    error.code = code;
 19	    if (details !== undefined) {
 20	        error.details = details;
 21	    }
 22	    return error;
 23	}
 24	
 25	export function deepFreeze(value) {
 26	    if (value !== null && typeof value === 'object' && !Object.isFrozen(value)) {
 27	        Object.freeze(value);
 28	        Object.values(value).forEach(deepFreeze);
 29	    }
 30	    return value;
 31	}
 32	
 33	export function isPlainObject(value) {
 34	    if (value === null || typeof value !== 'object' || Array.isArray(value)) {
 35	        return false;
 36	    }
 37	    const proto = Object.getPrototypeOf(value);
 38	    return proto === Object.prototype || proto === null;
 39	}
 40	
 41	function typesOf(prop) {
 42	    return Array.isArray(prop.type) ? prop.type : [prop.type];
 43	}
 44	
 45	// Picks the schema branch a value belongs to; constraints are then scoped to that branch
 46	// (e.g. an enum applies only to the string side of ['string','number']).
 47	function branchFor(types, value) {
 48	    if (value === null) {
 49	        return types.includes('null') ? 'null' : null;
 50	    }
 51	    if (typeof value === 'number') {
 52	        if (types.includes('integer') && Number.isInteger(value)) {
 53	            return 'integer';
 54	        }
 55	        return types.includes('number') && Number.isFinite(value) ? 'number' : null;
 56	    }
 57	    if (typeof value === 'boolean' || typeof value === 'string') {
 58	        return types.includes(typeof value) ? typeof value : null;
 59	    }
 60	    return types.includes('object') && isPlainObject(value) ? 'object' : null;
 61	}
 62	
 63	function checkRange(prop, value, field) {
 64	    if (Object.hasOwn(prop, 'minimum') && value < prop.minimum) {
 65	        throw new ParamError(field, `must be >= ${prop.minimum}`);
 66	    }
 67	    if (Object.hasOwn(prop, 'maximum') && value > prop.maximum) {
 68	        throw new ParamError(field, `must be <= ${prop.maximum}`);
 69	    }
 70	    return value;
 71	}
 72	
 73	function checkString(prop, value, field) {
 74	    if (Object.hasOwn(prop, 'maxLength') && value.length > prop.maxLength) {
 75	        throw new ParamError(field, `must be at most ${prop.maxLength} characters`);
 76	    }
 77	    if (Array.isArray(prop.enum) && !prop.enum.includes(value)) {
 78	        throw new ParamError(field, `must be one of ${prop.enum.filter((v) => typeof v === 'string').join(', ')}`);
 79	    }
 80	    if (typeof prop.pattern === 'string' && !new RegExp(prop.pattern).test(value)) {
 81	        throw new ParamError(field, `must match ${prop.pattern}`);
 82	    }
 83	    return value;
 84	}
 85	
 86	function checkValue(prop, value, field) {
 87	    const types = typesOf(prop);
 88	    const branch = branchFor(types, value);
 89	    if (branch === null) {
 90	        throw new ParamError(field, `must be of type ${types.join(' or ')}`);
 91	    }
 92	    if (branch === 'integer' || branch === 'number') {
 93	        return checkRange(prop, value, field);
 94	    }
 95	    if (branch === 'string') {
 96	        return checkString(prop, value, field);
 97	    }
 98	    if (branch === 'object') {
 99	        return validateObject(prop, value, {}, `${field}.`);
100	    }
101	    return value;
102	}
103	
104	function resolveValue(key, input, defaults, prop) {
105	    if (Object.hasOwn(input, key) && input[key] !== undefined) {
106	        return { present: true, value: input[key] };
107	    }
108	    if (Object.hasOwn(defaults, key) && defaults[key] !== undefined) {
109	        return { present: true, value: defaults[key] };
110	    }
111	    if (Object.hasOwn(prop, 'default')) {
112	        return { present: true, value: prop.default };
113	    }
114	    return { present: false };
115	}
116	
117	function validateObject(schema, input, defaults, prefix) {
118	    if (!isPlainObject(input)) {
119	        throw new ParamError(prefix ? prefix.slice(0, -1) : '(root)', 'must be a plain object');
120	    }
121	    const properties = schema.properties || {};
122	    for (const key of Object.keys(input)) {
123	        if (!Object.hasOwn(properties, key)) {
124	            throw new ParamError(`${prefix}${key}`, 'unknown parameter');
125	        }
126	    }
127	    const result = {};
128	    for (const key of Object.keys(properties)) {
129	        const resolved = resolveValue(key, input, defaults, properties[key]);
130	        if (resolved.present) {
131	            result[key] = checkValue(properties[key], resolved.value, `${prefix}${key}`);
132	        }
133	    }
134	    return Object.freeze(result);
135	}
136	
137	export function validateParams(schema, input, { defaults = {} } = {}) {
138	    if (!isPlainObject(defaults)) {
139	        throw new ParamError('(defaults)', 'must be a plain object');
140	    }
141	    return validateObject(schema, input, defaults, '');
142	}
143	
144	export function recommendedFor(model, runnerId) {
145	    const recommended = model?.recommended;
146	    if (!isPlainObject(recommended) || !Object.hasOwn(recommended, runnerId)) {
147	        return {};
148	    }
149	    return recommended[runnerId] || {};
150	}
151	
152	/** A runner's parameters: the input, then the model's recommended values, then the schema defaults. */
153	export function normalizeWith(schema, runnerId, params = {}, model = undefined) {
154	    return validateParams(schema, params, { defaults: recommendedFor(model, runnerId) });
155	}
