157	export function assertPort(port) {
158	    if (!Number.isInteger(port) || port < 1024 || port > 65535) {
159	        throw codedError('invalid_launch', 'port must be an integer between 1024 and 65535', { field: 'port' });
160	    }
161	    return port;
162	}
163	
164	export function assertApiKey(apiKey) {
165	    if (typeof apiKey !== 'string' || !API_KEY_PATTERN.test(apiKey)) {
166	        throw codedError('invalid_launch', 'apiKey must match /^[A-Za-z0-9_-]{32,128}$/', { field: 'apiKey' });
167	    }
168	    return apiKey;
169	}
170	
171	export function assertAbsolutePath(value, field) {
172	    if (typeof value !== 'string' || !isAbsolute(value) || value.includes('\0')) {
173	        throw codedError('invalid_launch', `${field} must be an absolute path`, { field });
174	    }
175	    return value;
176	}
