182	// Runs `<executable> <args>` without a shell and hands combined stdout+stderr to parse().
183	// Version probes get only what the executable needs to start, never the
184	// agent's tokens or secrets: the same rule as the runner environment.
185	export function probeEnv(extra = {}, source = process.env) {
186	    return {
187	        PATH: source.PATH || '/usr/local/nvidia/bin:/usr/local/bin:/usr/bin:/bin',
188	        HOME: source.HOME || '/tmp',
189	        LANG: 'C.UTF-8',
190	        ...extra,
191	    };
192	}
193	
194	export function probeVersion({ spawnSync, executable, args, env, parse, pinnedVersion }) {
195	    let result;
196	    try {
197	        result = spawnSync(executable, args, { encoding: 'utf8', timeout: PROBE_TIMEOUT_MS, env });
198	    } catch (error) {
199	        result = { error };
200	    }
201	    if (result?.error) {
202	        const reason = result.error.code === 'ENOENT'
203	            ? `Executable not found at ${executable}`
204	            : `Version probe failed: ${result.error.code || result.error.message}`;
205	        return { installed: false, version: null, reason };
206	    }
207	    const output = `${String(result?.stdout ?? '')}\n${String(result?.stderr ?? '')}`;
208	    const version = parse(output);
209	    if (!version) {
210	        return { installed: false, version: null, reason: `Unrecognized version output: ${snippet(output)}` };
211	    }
212	    const reason = version === pinnedVersion ? null : `Installed ${version} differs from pinned ${pinnedVersion}`;
213	    return { installed: true, version, reason };
214	}
