306	    const cacheTokens = params.cacheSize ?? params.maxSeqLen;
307	    const kvBytes = Math.round((model.memory?.kvBytesPerToken || DEFAULT_KV_BYTES_PER_TOKEN) * cacheTokens
308	        * (TABBY_CACHE_FACTOR[params.cacheMode] ?? 1));
309	    // ExLlamaV3 keeps the input embedding in system RAM (measured with
310	    // Qwen3-8B EXL3: 4,141 MiB on the GPU for a 4,966 MiB snapshot).
311	    const embeddingBytes = Math.min(size, model.memory?.embeddingBytes || 0);
312	    const gpuWeightsBytes = size - embeddingBytes;
313	    const gpuBytes = gpuWeightsBytes + kvBytes + TABBY_OVERHEAD_BYTES;
314	    const usable = gpu.totalBytes * VLLM_USABLE_SHARE;
315	    const ramBytes = VLLM_RUNNER_RAM_BYTES + embeddingBytes;
316	    const estimate = { weightsBytes: size, gpuWeightsBytes, cpuWeightsBytes: embeddingBytes, kvBytes, gpuBytes, ramBytes,
317	        basis: 'snapshot size, KV cache for cacheSize at cacheMode, and an estimated overhead' };
318	    const warnings = ramWarning(ramBytes, memory);
319	    if (gpuBytes > usable) {
320	        return result('incompatible', `Needs about ${gib(gpuBytes)} of GPU memory for its weights and a ${cacheTokens}-token `
321	            + `${params.cacheMode} cache; about ${gib(usable)} of this GPU is usable. Lower maxSeqLen, use cacheMode Q4, `
322	            + 'or pick a smaller model.', estimate, warnings);
323	    }
324	    if (memory.totalBytes && ramBytes > memory.totalBytes) {
325	        return result('incompatible', `Needs about ${gib(ramBytes)} of RAM; this machine has ${gib(memory.totalBytes)}.`, estimate, warnings);
326	    }
327	    if (gpuBytes > gpu.freeBytes - GPU_MARGIN_BYTES) {
328	        return result('insufficient-now', `Needs about ${gib(gpuBytes)} of GPU memory; ${gib(gpu.freeBytes)} is free now`
329	            + `${otherGpuUsers(gpu)}.`, estimate, warnings);
330	    }
331	    if (memory.availableBytes && ramBytes > memory.availableBytes - RAM_MARGIN_BYTES) {
332	        return result('insufficient-now', `Needs about ${gib(ramBytes)} of RAM; ${gib(memory.availableBytes)} is available now.`,
