114	export function validateHfSnapshotSource(value, field, { requirePin = false } = {}) {
115	    if (!plainObject(value)) throw invalid(`${field} must be an object`, field);
116	    if (value.type !== 'hf-snapshot') throw invalid(`${field}.type must be hf-snapshot`, `${field}.type`);
117	    onlyKeys(value, ['type', 'repo', 'revision', 'commit', 'files', 'size', 'quantization'], field);
118	    if (typeof value.repo !== 'string' || !HF_REPO_RE.test(value.repo)) {
119	        throw invalid(`${field}.repo must be a Hugging Face repository id (owner/name)`, `${field}.repo`);
120	    }
121	    const revision = value.revision ?? 'main';
122	    if (typeof revision !== 'string' || !HF_REVISION_RE.test(revision) || revision.includes('..')) {
123	        throw invalid(`${field}.revision is invalid`, `${field}.revision`);
124	    }
125	    const pinned = value.commit !== undefined || value.files !== undefined;
126	    const base = {
127	        type: 'hf-snapshot',
128	        repo: value.repo,
129	        revision,
130	        ...(value.quantization ? { quantization: optionalText(value.quantization, `${field}.quantization`, 64) } : {}),
131	    };
132	    if (!requirePin && !pinned) {
133	        if (value.size !== undefined) throw invalid(`${field}.size is computed from the pinned files`, `${field}.size`);
134	        return Object.freeze(base);
135	    }
136	    if (!COMMIT_RE.test(String(value.commit || ''))) throw invalid(`${field}.commit must be a 40-hex commit`, `${field}.commit`);
137	    if (!Array.isArray(value.files) || value.files.length === 0 || value.files.length > MAX_SNAPSHOT_FILES) {
138	        throw invalid(`${field}.files must list 1-${MAX_SNAPSHOT_FILES} files`, `${field}.files`);
139	    }
140	    const seen = new Set();
141	    const files = value.files.map((file, index) => {
142	        const at = `${field}.files[${index}]`;
143	        if (!plainObject(file)) throw invalid(`${at} must be an object`, at);
144	        onlyKeys(file, ['path', 'size', 'sha256', 'gitOid'], at);
145	        if (!isSnapshotFile(file.path)) {
146	            throw invalid(`${at}.path must be a top-level model file (.json, .safetensors, .txt, .model, .tiktoken or .jinja)`, `${at}.path`);
147	        }
148	        if (seen.has(file.path)) throw invalid(`${field}.files lists ${file.path} twice`, at);
149	        seen.add(file.path);
150	        if (!Number.isSafeInteger(file.size) || file.size <= 0) throw invalid(`${at}.size must be the file size in bytes`, `${at}.size`);
151	        if (file.sha256 === undefined && file.gitOid === undefined) {
152	            throw invalid(`${at} needs its sha256 or gitOid`, at);
153	        }
154	        if (file.sha256 !== undefined && !SHA256_RE.test(String(file.sha256))) throw invalid(`${at}.sha256 must be 64 hex`, `${at}.sha256`);
155	        if (file.gitOid !== undefined && !GIT_OID_RE.test(String(file.gitOid))) throw invalid(`${at}.gitOid must be 40 hex`, `${at}.gitOid`);
156	        return Object.freeze({
157	            path: file.path,
158	            size: file.size,
159	            ...(file.sha256 !== undefined ? { sha256: file.sha256 } : { gitOid: file.gitOid }),
160	        });
161	    });
162	    if (!files.some((file) => file.path.endsWith('.safetensors'))) {
163	        throw invalid(`${field}.files has no .safetensors file; vLLM and TabbyAPI read their weights from safetensors files`, `${field}.files`);
164	    }
165	    const size = files.reduce((sum, file) => sum + file.size, 0);
166	    if (value.size !== undefined && value.size !== size) {
167	        throw invalid(`${field}.size must equal the sum of the file sizes (${size})`, `${field}.size`);
168	    }
169	    return Object.freeze({ ...base, commit: value.commit, files: Object.freeze(files), size });
170	}
