272	/**
273	 * Bring a registry entry written by the v1 controller (sources keyed by
274	 * runner id) to schema v2 (keyed by weight format). Idempotent, and it never
275	 * throws: anything it cannot map is left for validation to refuse, so the
276	 * entry is hidden but kept rather than lost.
277	 */
278	export function migrateModelEntry(entry) {
279	    if (!plainObject(entry) || !plainObject(entry.sources)) return entry;
280	    const sources = {};
281	    for (const [key, source] of Object.entries(entry.sources)) {
282	        if (!V1_GGUF_KEYS.includes(key)) sources[key] = source;
283	    }
284	    if (!sources.gguf) {
285	        const legacy = V1_GGUF_KEYS.map((key) => entry.sources[key]).find((source) => source?.type === 'huggingface');
286	        if (legacy) sources.gguf = legacy;
287	    }
288	    const migrated = { ...entry, sources };
289	    const v1 = Object.keys(entry.sources).some((key) => V1_GGUF_KEYS.includes(key));
290	    if (!v1) return migrated;
291	    for (const field of ['recommended', 'validated']) {
292	        if (!plainObject(entry[field])) continue;
293	        migrated[field] = Object.fromEntries(Object.entries(entry[field]).filter(([runnerId]) => !V1_STUB_RUNNERS.includes(runnerId)));
