312	/**
313	 * Seed entries first, then valid user entries whose ids do not shadow a seed
314	 * or an earlier user entry (two can exist after a downgrade hid one).
315	 */
316	export function mergeCatalog(seed, registry = []) {
317	    const seenIds = new Set(seed.map((model) => model.id));
318	    const user = [];
319	    for (const entry of registry) {
320	        try {
321	            const model = validateModel(entry, { seed: false });
322	            if (seenIds.has(model.id)) continue;
323	            seenIds.add(model.id);
324	            user.push(model);
325	        } catch {
326	            // An invalid persisted entry is skipped, never allowed to break the catalog.
327	        }
328	    }
329	    return Object.freeze([...seed, ...user]);
330	}

